    /**
     * Sales Start At
     */
    sales_start_at?: string | null;
    /**
     * Sales End At
     */
    sales_end_at?: string | null;
    /**
     * Sales Paused
     */
    sales_paused?: boolean | null;
    /**
     * Total Quantity
     */
    total_quantity?: number | null;
    /**
     * Restricted To Membership Tiers Ids
     */
